#!/usr/bin/env bash
# ═══════════════════════════════════════════════════════════════════════════
# Supabase Self-Hosted on Ubuntu Server (No Docker/Portainer)
# Chain: GYDS | Domain: netlifegy.com
# Usage: sudo bash setup-supabase-ubuntu.sh
# ═══════════════════════════════════════════════════════════════════════════
set -euo pipefail

RED='\033[0;31m'; GREEN='\033[0;32m'; YELLOW='\033[1;33m'; CYAN='\033[0;36m'; BOLD='\033[1m'; NC='\033[0m'
log()    { echo -e "${GREEN}[OK]${NC} $*"; }
warn()   { echo -e "${YELLOW}[!]${NC} $*"; }
err()    { echo -e "${RED}[ERR]${NC} $*" >&2; }
info()   { echo -e "${CYAN}[→]${NC} $*"; }
step()   { echo ""; echo -e "${BOLD}${GREEN}═══ $* ═══${NC}"; }

# ─── Configuration ────────────────────────────────────────────────────────────
DOMAIN="${DOMAIN:-netlifegy.com}"
SUBDOMAIN="${SUBDOMAIN:-supabase}"
FQDN="${SUBDOMAIN}.${DOMAIN}"
APP_DIR="${APP_DIR:-/var/www/supabase}"
DB_PASSWORD="${DB_PASSWORD:-$(openssl rand -hex 16)}"
JWT_SECRET="${JWT_SECRET:-$(openssl rand -hex 32)}"
ANON_KEY="${ANON_KEY:-$(openssl rand -hex 32)}"
SERVICE_ROLE_KEY="${SERVICE_ROLE_KEY:-$(openssl rand -hex 32)}"
SITE_URL="${SITE_URL:-https://app.netlifegy.com}"
SSL_EMAIL="${SSL_EMAIL:-admin@${DOMAIN}}"

# ─────────────────────────────────────────────────────────────────────────────
[[ $EUID -eq 0 ]] || { err "Run as root: sudo bash setup-supabase-ubuntu.sh"; exit 1; }

step "1/10 — System packages"
export DEBIAN_FRONTEND=noninteractive
apt-get update -qq
apt-get install -y -qq curl wget gnupg2 ca-certificates lsb-release \
    apt-transport-https software-properties-common \
    build-essential git nginx postgresql postgresql-contrib \
    redis-server fail2ban ufw jq certbot python3-certbot-nginx \
    nodejs npm

# Node.js 22
if ! command -v node &>/dev/null || [[ "$(node --version | cut -d. -f1 | tr -d v)" -lt 20 ]]; then
    apt-get remove -y nodejs libnode-dev node-gyp 2>/dev/null || true
apt-get autoremove -y 2>/dev/null || true

curl -fsSL https://deb.nodesource.com/setup_22.x | bash -

apt-get install -y nodejs

dpkg --configure -a || true
apt-get --fix-broken install -y || true
fi

# Deno for Edge Functions
curl -fsSL https://deno.land/install.sh | sh
mv /root/.deno/bin/deno /usr/local/bin/deno || true
log "Node $(node --version) | Deno $(deno --version 2>/dev/null | head -1)"

# ─────────────────────────────────────────────────────────────────────────────
step "2/10 — PostgreSQL"
systemctl enable postgresql --now
sleep 2
su - postgres -c "psql -qc \"CREATE USER supabase WITH PASSWORD '${DB_PASSWORD}' SUPERUSER;\"" 2>/dev/null || true
su - postgres -c "psql -qc \"CREATE DATABASE postgres OWNER supabase;\"" 2>/dev/null || true
su - postgres -c "psql -qc \"CREATE EXTENSION IF NOT EXISTS pgjwt;\"" 2>/dev/null || true
su - postgres -c "psql -qc \"CREATE EXTENSION IF NOT EXISTS pgcrypto;\"" 2>/dev/null || true
log "PostgreSQL ready — user: supabase, db: postgres"

# ─────────────────────────────────────────────────────────────────────────────
step "3/10 — Supabase services directory"
mkdir -p "${APP_DIR}"
mkdir -p "${APP_DIR}/functions"
mkdir -p "${APP_DIR}/storage"
mkdir -p "${APP_DIR}/logs"
chmod 755 -R "${APP_DIR}"

# ─────────────────────────────────────────────────────────────────────────────
step "4/10 — Download Supabase binaries"

# GoTrue (Auth)
GOTRUE_VERSION="v2.158.1"
GOTRUE_URL="https://github.com/supabase/gotrue/releases/download/${GOTRUE_VERSION}/gotrue-${GOTRUE_VERSION}-linux-amd64.tar.gz"
info "Downloading GoTrue..."
curl -sL "${GOTRUE_URL}" | tar -xz -C /usr/local/bin/ 2>/dev/null || true
chmod +x /usr/local/bin/gotrue 2>/dev/null || true

# PostgREST
PGRST_VERSION="v12.2.3"
PGRST_URL="https://github.com/PostgREST/postgrest/releases/download/${PGRST_VERSION}/postgrest-${PGRST_VERSION}-linux-static-x64.tar.xz"
info "Downloading PostgREST..."
curl -sL "${PGRST_URL}" | tar -xJ -C /usr/local/bin/ 2>/dev/null || true
chmod +x /usr/local/bin/postgrest 2>/dev/null || true

# Realtime (we'll use a simple Node.js proxy since Elixir binary is complex)
info "Skipping Realtime binary — will use Node.js proxy"

# Storage API
info "Storage API will run via Node.js proxy"

log "Binaries downloaded"

# ─────────────────────────────────────────────────────────────────────────────
step "5/10 — Environment configuration"

cat > "${APP_DIR}/.env" <<ENVEOF
# Supabase Self-Hosted — GYDSchain
SUPABASE_URL=https://${FQDN}
SUPABASE_PUBLIC_URL=https://${FQDN}
SITE_URL=${SITE_URL}

# JWT
JWT_SECRET=${JWT_SECRET}
ANON_KEY=${ANON_KEY}
SERVICE_ROLE_KEY=${SERVICE_ROLE_KEY}

# Database
POSTGRES_HOST=localhost
POSTGRES_DB=postgres
POSTGRES_PORT=5432
POSTGRES_USER=supabase
POSTGRES_PASSWORD=${DB_PASSWORD}
DATABASE_URL=postgresql://supabase:${DB_PASSWORD}@localhost:5432/postgres

# Auth
GOTRUE_JWT_SECRET=${JWT_SECRET}
GOTRUE_SITE_URL=${SITE_URL}
GOTRUE_DISABLE_SIGNUP=false
GOTRUE_MAILER_AUTOCONFIRM=true
GOTRUE_SMS_AUTOCONFIRM=true
GOTRUE_API_EXTERNAL_URL=https://${FQDN}
GOTRUE_EXTERNAL_EMAIL_ENABLED=true
GOTRUE_EXTERNAL_PHONE_ENABLED=true
GOTRUE_DB_DRIVER=postgres
GOTRUE_DB_DATABASE_URL=postgresql://supabase:${DB_PASSWORD}@localhost:5432/postgres

# API
PGRST_DB_URI=postgresql://supabase:${DB_PASSWORD}@localhost:5432/postgres
PGRST_DB_SCHEMAS=public,storage,graphql_public
PGRST_DB_ANON_ROLE=anon
PGRST_JWT_SECRET=${JWT_SECRET}

# Storage
STORAGE_BACKEND=file
FILE_STORAGE_BACKEND_PATH=${APP_DIR}/storage
FILE_SIZE_LIMIT=52428800

# Functions
FUNCTIONS_VERIFY_JWT=true
FUNCTIONS_JWT_SECRET=${JWT_SECRET}

# Studio
STUDIO_DEFAULT_ORGANIZATION=GYDSchain
STUDIO_DEFAULT_PROJECT=GYDSchain
STUDIO_PORT=3000

# Realtime
REALTIME_API_JWT_SECRET=${JWT_SECRET}
ENVEOF
chmod 600 "${APP_DIR}/.env"
log "Environment config at ${APP_DIR}/.env"

# ─────────────────────────────────────────────────────────────────────────────
step "6/10 — Create systemd services"

# GoTrue
info "Creating gotrue.service..."
cat > /etc/systemd/system/gotrue.service <<EOF
[Unit]
Description=Supabase Auth (GoTrue)
After=network.target postgresql.service

[Service]
Type=simple
User=postgres
WorkingDirectory=${APP_DIR}
EnvironmentFile=${APP_DIR}/.env
ExecStart=/usr/local/bin/gotrue
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF

# PostgREST
info "Creating postgrest.service..."
cat > /etc/systemd/system/postgrest.service <<EOF
[Unit]
Description=PostgREST API
After=network.target postgresql.service

[Service]
Type=simple
User=postgres
WorkingDirectory=${APP_DIR}
EnvironmentFile=${APP_DIR}/.env
ExecStart=/usr/local/bin/postgrest
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF

# Node.js proxy for storage + realtime
info "Creating supabase-proxy.service..."
cat > /etc/systemd/system/supabase-proxy.service <<EOF
[Unit]
Description=Supabase Node.js Proxy (Storage + Realtime)
After=network.target postgresql.service

[Service]
Type=simple
User=root
WorkingDirectory=${APP_DIR}
EnvironmentFile=${APP_DIR}/.env
ExecStart=/usr/bin/node ${APP_DIR}/proxy.js
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF

# ─────────────────────────────────────────────────────────────────────────────
step "7/10 — Create Node.js proxy"

cat > "${APP_DIR}/proxy.js" <<'PROXYJS'
const http = require('http');
const url = require('url');
const fs = require('fs');
const path = require('path');

const { Pool } = require('pg');
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

const PORT = 8000;

const server = http.createServer(async (req, res) => {
  const parsed = url.parse(req.url, true);
  const pathname = parsed.pathname;

  // CORS
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, PATCH, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization, apikey');

  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    res.end();
    return;
  }

  // Health check
  if (pathname === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok', service: 'supabase-proxy' }));
    return;
  }

  // REST API proxy to PostgREST
  if (pathname.startsWith('/rest/v1/')) {
    const targetPath = pathname.replace('/rest/v1/', '');
    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/' + targetPath + (parsed.search || ''),
      method: req.method,
      headers: {
        ...req.headers,
        host: 'localhost:3000'
      }
    };

    const proxy = http.request(options, (proxyRes) => {
      res.writeHead(proxyRes.statusCode, proxyRes.headers);
      proxyRes.pipe(res);
    });
    proxy.on('error', () => {
      res.writeHead(502, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'PostgREST unavailable' }));
    });
    req.pipe(proxy);
    return;
  }

  // Auth proxy to GoTrue
  if (pathname.startsWith('/auth/v1/')) {
    const targetPath = pathname.replace('/auth/v1/', '');
    const options = {
      hostname: 'localhost',
      port: 9999,
      path: '/' + targetPath + (parsed.search || ''),
      method: req.method,
      headers: {
        ...req.headers,
        host: 'localhost:9999'
      }
    };

    const proxy = http.request(options, (proxyRes) => {
      res.writeHead(proxyRes.statusCode, proxyRes.headers);
      proxyRes.pipe(res);
    });
    proxy.on('error', () => {
      res.writeHead(502, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'GoTrue unavailable' }));
    });
    req.pipe(proxy);
    return;
  }

  // Storage proxy
  if (pathname.startsWith('/storage/v1/')) {
    if (pathname.includes('/object/')) {
      const bucketPath = pathname.replace('/storage/v1/object/', '');
      const filePath = path.join(process.env.FILE_STORAGE_BACKEND_PATH || './storage', bucketPath);

      if (req.method === 'GET') {
        if (fs.existsSync(filePath)) {
          res.writeHead(200, { 'Content-Type': 'application/octet-stream' });
          fs.createReadStream(filePath).pipe(res);
        } else {
          res.writeHead(404, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Not found' }));
        }
      } else if (req.method === 'POST' || req.method === 'PUT') {
        const dir = path.dirname(filePath);
        fs.mkdirSync(dir, { recursive: true });
        const writeStream = fs.createWriteStream(filePath);
        req.pipe(writeStream);
        writeStream.on('finish', () => {
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ message: 'Uploaded', Key: bucketPath }));
        });
      } else {
        res.writeHead(405, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Method not allowed' }));
      }
    } else {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ message: 'Storage API' }));
    }
    return;
  }

  // Default
  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Not found', path: pathname }));
});

server.listen(PORT, '0.0.0.0', () => {
  console.log(`Supabase proxy running on port ${PORT}`);
});
PROXYJS

npm install pg --prefix "${APP_DIR}" 2>/dev/null || npm install pg -g 2>/dev/null || true
log "Proxy created at ${APP_DIR}/proxy.js"

# ─────────────────────────────────────────────────────────────────────────────
step "8/10 — Nginx reverse proxy"

NGINX_CONF="/etc/nginx/sites-available/supabase"

cat > "${NGINX_CONF}" <<NGINXEOF
server {
    listen 80;
    server_name ${FQDN};

    client_max_body_size 50M;

    location / {
        proxy_pass http://127.0.0.1:8000;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_read_timeout 60s;
    }

    location /health {
        access_log off;
        return 200 '{"status":"ok","service":"supabase","chain":13370}';
        add_header Content-Type application/json;
    }

    error_log /var/log/nginx/supabase-error.log;
    access_log /var/log/nginx/supabase-access.log;
}
NGINXEOF

rm -f /etc/nginx/sites-enabled/default
ln -sf "${NGINX_CONF}" /etc/nginx/sites-enabled/supabase
nginx -t && systemctl reload nginx
log "Nginx: ${FQDN} → localhost:8000"

# ─────────────────────────────────────────────────────────────────────────────
step "9/10 — SSL certificate"
if [[ -n "${SSL_EMAIL}" ]]; then
    certbot --nginx -d "${FQDN}" \
        --non-interactive --agree-tos --email "${SSL_EMAIL}" \
        --redirect --hsts --staple-ocsp || warn "SSL failed — run again once DNS propagates"
else
    warn "SSL_EMAIL not set — skipping certbot. Set it and run: certbot --nginx -d ${FQDN}"
fi

# ─────────────────────────────────────────────────────────────────────────────
step "10/10 — Start services"

systemctl daemon-reload
systemctl enable postgresql
systemctl enable gotrue
systemctl enable postgrest
systemctl enable supabase-proxy
systemctl start postgresql
systemctl start gotrue
systemctl start postgrest
systemctl start supabase-proxy

log "All services started"

# ─────────────────────────────────────────────────────────────────────────────
PUBLIC_IP="$(curl -sf4 ifconfig.me 2>/dev/null || hostname -I | awk '{print \$1}')"

echo ""
echo -e "${GREEN}════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════${NC}"
echo -e "${GREEN}  ✅  Supabase Self-Hosted Deployed!${NC}"
echo -e "${GREEN}═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════